/* The one place that turns a hero's three choices into numbers. Every page calls this.
   sel = { p:"human", s:"orc" | "human" | {custom:{attr:"vit",social:"Stealth"}},
           t:"veilkin" | "orc" | {custom:{tpl:"heal",name:"..."}} }  — s and t may be null. */
GAMEDATA.ancestryTotals = function(sel){
  var R={vit:0,echo:0,aen:0,move:0,charges:0,socials:[],abilities:[],steps:[]};
  if(!sel||!sel.p) return R;
  var A=GAMEDATA.ancestries, C=GAMEDATA.ancestryCustom;
  function byId(id){ for(var i=0;i<A.length;i++) if(A[i].id===id) return A[i]; return null }
  function add(b,label){ if(!b) return; ['vit','echo','aen','move','charges'].forEach(function(k){ if(b[k]) R[k]+=b[k] });
    if(b.social) R.socials.push(b.social); if(b.ability) R.abilities.push(b.ability); R.steps.push(label) }
  var p=byId(sel.p); if(!p||!p.primordial) return R;
  add(p.primordial, p.name);
  var s=sel.s, lineId=p.id;
  if(s&&typeof s==='object'&&s.custom){
    var at=null; (C.step2.attrs||[]).forEach(function(a){ if(a.id===s.custom.attr) at=a });
    var b2={}; if(at) ['vit','echo','aen','move','charges'].forEach(function(k){ if(at[k]) b2[k]=at[k] });
    if(s.custom.social) b2.social=s.custom.social;
    add(b2, 'Custom');
  } else if(typeof s==='string'){
    var r2=byId(s);
    if(r2){ if(r2.id===p.id) add(r2.reinforce2, r2.name+' (reinforced)'); else if(r2.pick2){ add(r2.pick2, r2.name); lineId=r2.id } }
  }
  var tt=sel.t;
  if(tt&&typeof tt==='object'&&tt.custom){
    var tp=null; (C.step3.abilities||[]).forEach(function(a){ if(a.id===tt.custom.tpl) tp=a });
    if(tp) add({ability:{name:tt.custom.name||'Custom ability',desc:tp.label}}, 'Custom');
  } else if(typeof tt==='string'){
    var r3=byId(tt);
    if(r3){ if(r3.id===lineId&&r3.reinforce3) add(r3.reinforce3, r3.name+' (reinforced)'); else if(r3.pick3) add(r3.pick3, r3.name); }
  }
  return R;
};

