GAMEDATA.masteryRules = { "marks": "One mark buys one node. Nodes open in order inside a branch; each tier declares its own gate.", "dice": "The trunk Root gives 2d12 keep highest with that weapon family. A branch Mastery gives 3d12 with that weapon only.", "signature": "Only one signature fires per attack — you wield one weapon at a time.", "lowBand": "Each branch grants its band 1-4 signature free, the moment you buy your first node in it.", "reaction": "One reaction per round, free, outside your turn. No Aen, no action.",
  "identityReaction": "Your subclass Base ability can ALSO be used as your one reaction per round, when its trigger occurs. Unlike tree reactions it costs its normal Aen, and its Drawback applies. The ability text does not change; this adds a second moment to use it, it does not replace the action use. One reaction per round total: choose between this, tree reactions and kit reactions.", "interplane": [ "One Legendary per session per character, not per node.", "Only one Interplane effect can be active per encounter, across the whole party.", "Effects that remove a creature from the fight do not work on hard or boss: they lose one action instead." ] };

