GAMEDATA.armorTreeFor = function(kitId){ return (GAMEDATA.armorTrees||[]).find(function(a){ return a.kitId===kitId })||null };

/* ── Monster scale by party level ── baseBestiary is level 1. Vitality ×(1+0.20·(L−1)), damage ×(1+0.15·(L−1)); Vitality 1 stays 1 (minions fall in one hit by design). Abilities and conditions do not scale. */
GAMEDATA.monsterScale = { "hpPerLevel": 0.20, "dmgPerLevel": 0.15 };
GAMEDATA.scaleMonster = function(m, L){ L=Math.max(1,Math.min(10,parseInt(L)||1)); var s=GAMEDATA.monsterScale, fh=1+s.hpPerLevel*(L-1), fd=1+s.dmgPerLevel*(L-1); var hp=(m.hp===1)?1:Math.round(m.hp*fh); var dmg=String(m.dmg==null?"":m.dmg), x=dmg.match(/^(\d+)\s*-\s*(\d+)$/), dmgScaled=dmg, scaledDmg=true; if(x){ dmgScaled=Math.round(+x[1]*fd)+"-"+Math.round(+x[2]*fd) } else if(/^\d+$/.test(dmg)){ dmgScaled=String(Math.round(+dmg*fd)) } else { scaledDmg=false } return { level:L, hp:hp, dmg:dmgScaled, dmgScaled:scaledDmg, hpFactor:fh, dmgFactor:fd } };
